contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Ensure caller is not the admin (admin is the deployer of setUp)
        vm.assume(caller != address(this));
        // Record owner before the call
        address ownerBefore = c.owner();
        // Attempt to set owner from a non-admin caller
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        // For non-admin, the reference always reverts or keeps owner unchanged, so owner must remain ownerBefore
        assertTrue(c.owner() == ownerBefore);
    }
}

