pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(address caller) public {
        // 1. Restrict to admissible domain: caller not the admin, and have a distinct new owner
        vm.assume(caller != address(this)); // setUp deploys c, admin is this address in reference
        vm.assume(caller != address(0));
        address newOwner = address(uint160(uint256(keccak256(abi.encode(caller)))));
        vm.assume(newOwner != address(0));
        // 2. Record original owner, attempt setOwner as fuzzed caller
        address originalOwner = c.owner();
        vm.prank(caller);
        bool success = c.setOwner(newOwner);
        // 3. Assert: if success, the caller must have been the admin (this contracts setUp deployer)
        // Since caller != admin by vm.assume, success should be false in reference, but true in mutant
        // The property: setOwner only succeeds when caller is admin.
        // We cannot perfectly encode admin without hardcoding privilege, so we check:
        // If setOwner succeeded, then caller must have been the admin contract (original deployer).
        // Since we assumed caller != this address, success must be false in reference.
        // In mutant, success can be true and owner changes, violating the invariant below.
        // We encode the invariant as: if setOwner did not revert (success == true), then owner MUST equal newOwner
        // but that holds in both. The better invariant: setOwner never causes owner to change for a non-admin caller.
        // After the call, if the owner changed AND caller != admin, invariant broken.
        address afterOwner = c.owner();
        assertTrue(afterOwner == originalOwner || caller == address(this));
    }
}

