pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonAdmin) public {
        // nonAdmin must not be the original admin (msg.sender in setUp, i.e. this contract address)
        vm.assume(nonAdmin != address(this));
        // record the owner before the call
        address ownerBefore = c.owner();
        // nonAdmin tries to call setOwner to change the owner to an arbitrary address (here we use address(0x1234) as a non-zero address; the fuzzer explores the caller, the target is fixed to a non-zero address to avoid accidentally setting to the same address)
        vm.prank(nonAdmin);
        (bool success, bytes memory retData) = address(c).call(abi.encodeWithSignature("setOwner(address)", address(0x1234)));
        // if the reference contract is correct, the call either reverts or does not change owner
        // If the call reverts (success == false), owner remains unchanged (ownerBefore)
        // If the call does not revert (success == true), owner must still be unchanged (enforced by onlyAdmin)
        // The buggy version will succeed (success == true) AND change the owner to address(0x1234)
        address ownerAfter = c.owner();
        bool pass = (ownerAfter == ownerBefore);
        assertTrue(pass);
    }
}

