// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adminCaller, address newOwner1, address newOwner2) public {
        // adminCaller must be the original admin (constructor msg.sender) to be allowed to set owner initially
        vm.assume(adminCaller != address(0));
        vm.assume(newOwner1 != address(0));
        vm.assume(newOwner2 != address(0));
        vm.assume(newOwner1 != newOwner2);
        // ensure adminCaller is the reference admin (deployer)
        // deployer is this test contract, so we need to prank as the test contract (which deployed c)
        // The admin is set in the constructor to msg.sender, which is this InvMutTest contract.
        // So we use adminCaller in place of the deployer by pranking as the test contract itself.
        // Actually, admin is payable(msg.sender) in constructor, so admin = address(this) of InvMutTest.
        // We restrict adminCaller to be address(this) to match the deployed admin.
        vm.assume(adminCaller == address(this));

        // Step 1: admin sets owner to newOwner1
        vm.prank(adminCaller);
        c.setOwner(newOwner1);

        // Step 2: newOwner1 attempts to set owner to newOwner2
        vm.prank(newOwner1);
        try c.setOwner(newOwner2) returns (bool success) {
            // If the call succeeds, owner must be newOwner2.
            // However, only the original admin should be able to change owner.
            // In the reference, only admin can call setOwner, so newOwner1's call reverts.
            // In the buggy version, owner can call setOwner, so newOwner1's call succeeds.
            // After this, the owner in reference remains newOwner1, but in buggy it becomes newOwner2.
            // We capture the final owner and assert it is one of {adminCaller, newOwner1}.
            // In reference: owner == newOwner1 (passes). In buggy: owner == newOwner2 (fails).
            address finalOwner = c.owner();
            bool isAdminOrFirstOwner = (finalOwner == adminCaller || finalOwner == newOwner1);
            assertTrue(isAdminOrFirstOwner);
        } catch {
            // If it reverts, owner must still be newOwner1 in both cases.
            // In reference, it always reverts here, so owner is newOwner1.
            // In buggy, it might revert if newOwner1 is not the admin and not the owner (but here newOwner1 is owner).
            // So buggy will NOT revert here; it will succeed if newOwner1 is owner.
            // The catch block won't be reached in buggy, so no assertion is needed.
            // We still assert the owner is newOwner1 for the reference case.
            assertTrue(c.owner() == newOwner1);
        }
    }
}

