pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner) public {
        // The msg.sender of setUp (this contract) is the admin, so we can call setOwner directly.
        // setOwner does not revert for any address owner when called by the admin, so no assume needed.
        bool ret = c.setOwner(owner);
        // The general rule: a successful setOwner call by the admin always returns true.
        assertTrue(ret);
    }
}
